import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.DGvnA5EY.js";const l="/workbuddy-guide/assets/01-remote-control.DJqUOJ7r.png",b=JSON.parse('{"title":"第 13 章 远程控制你的电脑，不用发愁不在电脑前","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 这一章是第一篇第 8 章（接入 IM 助理）的实战版。第 8 章教你把微信/企微/飞书等 \\"遥控器\\"接上，这一章带你用它真干一件：人不在电脑前，也能让家里的电脑替你跑任务、 找文件、把结果发回手机。","frontmatter":{"title":"第 13 章 远程控制你的电脑，不用发愁不在电脑前"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 远程控制你的电脑，不用发愁不在电脑前/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 远程控制你的电脑，不用发愁不在电脑前/index.md","lastUpdated":1791615980000}'),r={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 远程控制你的电脑，不用发愁不在电脑前/index.md"};function s(i,t,n,h,p,u){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="第-13-章-远程控制你的电脑-不用发愁不在电脑前" tabindex="-1">第 13 章 远程控制你的电脑，不用发愁不在电脑前 <a class="header-anchor" href="#第-13-章-远程控制你的电脑-不用发愁不在电脑前" aria-label="Permalink to &quot;第 13 章 远程控制你的电脑，不用发愁不在电脑前&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>这一章是<strong>第一篇第 8 章（接入 IM 助理）的实战版</strong>。第 8 章教你把微信/企微/飞书等 &quot;遥控器&quot;接上，这一章带你用它真干一件：人不在电脑前，也能让家里的电脑替你跑任务、 找文件、把结果发回手机。</p><p><img src="'+l+`" alt="一只小黑躺在沙发上用手机发指令，远处的电脑亮着屏在干活" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;远程控制&quot;，与实际软件界面无关。</em></p><h2 id="一、最爽的几个场景-痛点" tabindex="-1">一、最爽的几个场景（痛点） <a class="header-anchor" href="#一、最爽的几个场景-痛点" aria-label="Permalink to &quot;一、最爽的几个场景（痛点）&quot;">​</a></h2><ul><li>你在外面，突然要一份存在家里电脑上的合同</li><li>想让电脑开始跑一个长任务（下载、转码、批量处理），人不用守着</li><li>同事发来一个文件，你希望电脑自动归到对应项目目录</li></ul><p>这些事过去要装远程桌面软件、记 IP、调端口。用了 IM 助理，直接手机发一句话就办了。</p><h2 id="二、前提条件-先确认这几样" tabindex="-1">二、前提条件（先确认这几样） <a class="header-anchor" href="#二、前提条件-先确认这几样" aria-label="Permalink to &quot;二、前提条件（先确认这几样）&quot;">​</a></h2><ul><li>家里的电脑<strong>开机且联网</strong>（关了或断网就接不到指令）</li><li>已经接好 IM 助理（微信/企微/飞书/钉钉/QQ），接法见第一篇第 8 章</li><li>电脑上的 WorkBuddy 处于可接收远程任务的状态</li></ul><p>如果没准备好，先回第 8 章把&quot;遥控器&quot;配好，再来玩这章。</p><h2 id="三、先选对-skill-远程控制的组合" tabindex="-1">三、先选对 Skill：远程控制的组合 <a class="header-anchor" href="#三、先选对-skill-远程控制的组合" aria-label="Permalink to &quot;三、先选对 Skill：远程控制的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>IM 助理（微信/企微/飞书/钉钉/QQ）</strong></td><td>手机发指令、收结果</td><td>远程任务的&quot;遥控器&quot;入口</td><td>必须先接入，见第一篇第 8 章</td></tr><tr><td><strong>本地 Agent</strong></td><td>在电脑上执行找文件/转格式/跑脚本</td><td>收到指令后在本地干活</td><td>权限确认开着，不开全自动</td></tr><tr><td><strong>自动化（第一篇第 10 章）</strong></td><td>到点自动干，连发指令都省</td><td>&quot;每天 9 点把下载归档&quot;</td><td>配合远程，无人值守要谨慎</td></tr><tr><td><strong>skill-creator（零成本）</strong></td><td>把常用远程指令固化</td><td>&quot;把 X 类文件转 Word 发我&quot;做成技能</td><td>跑顺后固化</td></tr></tbody></table><h2 id="四、真实可复制提示词-在手机上发" tabindex="-1">四、真实可复制提示词（在手机上发） <a class="header-anchor" href="#四、真实可复制提示词-在手机上发" aria-label="Permalink to &quot;四、真实可复制提示词（在手机上发）&quot;">​</a></h2><h3 id="提示词-1-找文件发我" tabindex="-1">提示词 1｜找文件发我 <a class="header-anchor" href="#提示词-1-找文件发我" aria-label="Permalink to &quot;提示词 1｜找文件发我&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我在 D 盘/合同 里找一下上个月签的租房合同，把文件名和所在路径发我。</span></span>
<span class="line"><span>如果找到了，把文件通过微信发给我。</span></span></code></pre></div><h3 id="提示词-2-转格式再回传" tabindex="-1">提示词 2｜转格式再回传 <a class="header-anchor" href="#提示词-2-转格式再回传" aria-label="Permalink to &quot;提示词 2｜转格式再回传&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把桌面上的【季度汇报.pdf】转成 Word 文档，转好后发到我微信。</span></span>
<span class="line"><span>先确认源文件存在，再转换；转换完告诉我字数和新文件位置。</span></span></code></pre></div><h3 id="提示词-3-启动一个长任务并通知" tabindex="-1">提示词 3｜启动一个长任务并通知 <a class="header-anchor" href="#提示词-3-启动一个长任务并通知" aria-label="Permalink to &quot;提示词 3｜启动一个长任务并通知&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开始跑【视频转码】这个长任务（脚本在 D 盘/批处理/transcode.bat），</span></span>
<span class="line"><span>跑完之后在微信里通知我&quot;转码完成&quot;，并把输出目录列给我。</span></span>
<span class="line"><span>中途如果报错，也发微信告诉我报错内容，不要自己重试超过两次。</span></span></code></pre></div><h2 id="五、执行步骤表" tabindex="-1">五、执行步骤表 <a class="header-anchor" href="#五、执行步骤表" aria-label="Permalink to &quot;五、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>发生什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>你在微信给助理发任务描述</td><td>说清要什么、在哪、给什么结果</td></tr><tr><td>2</td><td>电脑端收到，开始执行（你能看到它在动）</td><td>执行的是不是你想要的，必要时喊停</td></tr><tr><td>3</td><td>执行完，结果回传手机（文字/文件/推送）</td><td>结果对不对、文件有没有收到</td></tr><tr><td>4</td><td>（可选）自动化到点自动干</td><td>无人值守的任务是否安全</td></tr></tbody></table><h2 id="六、能远程做的-vs-最好别远程做的" tabindex="-1">六、能远程做的 vs 最好别远程做的 <a class="header-anchor" href="#六、能远程做的-vs-最好别远程做的" aria-label="Permalink to &quot;六、能远程做的 vs 最好别远程做的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>适合远程</th><th>谨慎远程（需你确认）</th></tr></thead><tbody><tr><td>找文件、读内容、生成文档</td><td>大批量删文件（见第 12 章安全底线）</td></tr><tr><td>跑已知流程的脚本/任务</td><td>涉及资金、重要账号的操作</td></tr><tr><td>让电脑开始一个长任务</td><td>需要你现场判断的模糊决策</td></tr></tbody></table><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：你躺在沙发上，手机收到文件或一条&quot;已完成&quot;的推送。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 指令被执行，且结果与描述一致（文件路径/内容对得上）</li><li>[ ] 敏感操作有确认环节，没有&quot;全自动批准&quot;放行</li><li>[ ] 结果正确回传到手机（你能打开/看到）</li></ul><h2 id="八、一个必须记住的坑" tabindex="-1">八、一个必须记住的坑 <a class="header-anchor" href="#八、一个必须记住的坑" aria-label="Permalink to &quot;八、一个必须记住的坑&quot;">​</a></h2><p>远程执行和本地一样，都要<strong>权限确认</strong>。别为了图方便在远程场景下放开&quot;全自动批准&quot;—— 你人在外面，一旦指令被误触发，后果更难当场补救。另外，公共 Wi-Fi 下尽量不发 敏感指令，防被窥探。</p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>远程任务</strong>：你不在电脑旁，通过手机/IM 把任务发到电脑上执行。</p><p><strong>端到端</strong>：从你发指令到收到结果，整条链路自动跑通，中间不用你守着。</p><p><strong>IM 助理</strong>：WorkBuddy 接在微信/企微等里的&quot;遥控器&quot;，让你用聊天发任务。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 确认家里的电脑已接好 IM 助理且能联网</li><li>[ ] 用手机发一条&quot;找文件&quot;的小任务，验证回传</li><li>[ ] （进阶）把最常用的远程指令用 skill-creator 固化成技能</li><li>[ ] 给自己定规矩：远程不开全自动批准，敏感操作不远程</li></ul><hr><p><em>下一篇：第 14 章——生活助手的价值，是减少琐碎。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,38)])])}const q=a(r,[["render",s]]);export{b as __pageData,q as default};
